const fs=require('fs');
const s=fs.readFileSync('src/views/TodayStockRecommendation.vue','utf8');
// 提取 template 块
const t=s.match(/<template>([\s\S]*?)<\/template>/);
if(!t){console.log('NO TEMPLATE');process.exit(1)}
// 简单标签配对检查
const html=t[1];
const stack=[];
const re=/<\/?([a-zA-Z][a-zA-Z0-9-]*)((?:\"[^\"]*\"|'[^']*'|[^'\">])*)>/g;
let m,err=null;
while((m=re.exec(html))){
  const full=m[0],tag=m[1];
  if(full.startsWith('</')){
    const top=stack.pop();
    if(top!==tag){err='Mismatch: expected </'+top+'> got </'+tag+'>';break}
  } else if(!full.endsWith('/>')){
    stack.push(tag);
  }
}
if(err)console.log('TEMPLATE ERROR:',err);
else if(stack.length)console.log('UNCLOSED:',stack.join(','));
else console.log('TEMPLATE OK - all tags balanced');
""}

